export function HtmlElement({
  pageTitle = "{{pageTitle}}",
  lang = "{{lang}}",
  accent = "{{accent}}",
  showChildren = {{showChildren}},
}) {
  return (
    <div style={{ width: 460, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12 }}>
      <p style={{ margin: "0 0 14px", fontSize: 13, color: "#241430aa" }}>
        Document outline — <code style={{ background: "#24143012", padding: "1px 5px", borderRadius: 4 }}>{`<html lang="${lang}">`}</code> is the root, wrapping everything else
      </p>
      <div style={{ borderRadius: 8, padding: 12, boxSizing: "border-box", border: `2.5px solid ${accent}`, background: `color-mix(in srgb, ${accent} 10%, #FAF7F2)` }}>
        <span style={{ display: "block", font: "700 12px/1 ui-monospace, monospace", color: accent, marginBottom: 4 }}>{`<html lang="${lang}">`}</span>
        {showChildren && (
          <div style={{ display: "flex", gap: 10, marginTop: 10 }}>
            <div style={{ flex: 1, border: "1.5px dashed #24143035", borderRadius: 8, padding: 12 }}>
              <span style={{ display: "block", font: "700 12px/1 ui-monospace, monospace", color: "#24143070", marginBottom: 4 }}>&lt;head&gt;</span>
              <span style={{ display: "block", fontSize: 11, color: "#241430aa" }}>{pageTitle}</span>
            </div>
            <div style={{ flex: 1, border: "1.5px dashed #24143035", borderRadius: 8, padding: 12 }}>
              <span style={{ display: "block", font: "700 12px/1 ui-monospace, monospace", color: "#24143070", marginBottom: 4 }}>&lt;body&gt;</span>
              <span style={{ display: "block", fontSize: 11, color: "#241430aa" }}>visible page content</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
